import {simpleSizing} from './position-sizing.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=input=>input.value.trim()===''?null:Number(input.value);
const fmt=(value,digits=2)=>Number.isFinite(value)?value.toLocaleString('zh-CN',{maximumFractionDigits:digits}):'待填写';
const manualDrafts=new Map();

export function mountGoldSizing(node,{card,accounts,api,onChange}){
 const saved=card.id?manualDrafts.get(card.id):null;
 let available=accounts.filter(a=>a.status==='active'),spec=null,source=null,manual=!!saved,revision=0,cycle=saved?.mainCycle||card.plan?.payload.mainCycle||'day',methodCap=null,suppress=false;
 const p=saved||card.plan?.payload||{};
 node.innerHTML=`<form id="goldSizingForm" class="gold-sizing form-section" aria-label="以损定量"><div class="section-head"><div><h3>以损定量</h3><p>入场价、止损价由你填写或修改，按实际账户余额自动计算手数。</p></div><button type="button" class="secondary" id="goldSizingRefresh">更新账户余额</button></div><div class="form-grid three"><label class="field">品种 / 具体合约<input id="goldSizingProduct" readonly value="${esc(card.name)} · ${esc(card.contract||card.symbol)}"></label><label class="field">测算账户<select id="goldSizingAccount" name="sizingAccount">${available.map(a=>`<option value="${esc(a.id)}" ${a.id===(saved?.accountId||card.accountId)?'selected':''}>${esc(a.alias)}</option>`).join('')}</select></label><label class="field calculated">实际账户余额（元）<input id="goldSizingEquity" readonly></label><label class="field">亏损比例（%）<input id="goldSizingPercent" name="sizingPercent" type="number" min="0.001" max="1" step="0.001" value="${p.riskPercent??1}"></label><label class="field">计划入场价<input id="goldSizingEntry" name="sizingEntry" type="number" min="0" step="any" value="${p.entry??''}" placeholder="由本人填写"></label><label class="field">止损保护价<input id="goldSizingStop" name="sizingStop" type="number" min="0" step="any" value="${p.stop??''}" placeholder="由本人填写"></label></div><p class="gold-sizing-suggestion" id="goldSizingSuggestion">分析或确认手法后可带入建议价格，你仍可修改。</p><div class="gold-sizing-metrics" aria-live="polite"><div><small>可承受亏损金额（元）</small><output id="goldSizingBudget">待填写</output></div><div><small>止损距离（点）</small><output id="goldSizingDistance">待填写</output></div><div><small>每手止损金额（元）</small><output id="goldSizingPerLot">待填写</output></div><div class="gold-sizing-quantity"><small>按止损价差可开手数（手）</small><output id="goldSizingLots">待填写</output></div></div><p id="goldSizingSpec" class="muted">正在核对该品种每点金额和最小变动价位…</p><p id="goldSizingFeedback" role="status"></p><p class="muted">手数向下取整；下方审定继续核对本轮余额度与账户限制。仅试算不会保存或批准计划。</p><button type="button" class="secondary" id="goldSizingSuggestionButton" disabled>采用最新建议价格</button></form>`;
 const $=s=>node.querySelector(s),getAccount=()=>available.find(a=>a.id===$('#goldSizingAccount').value),cap=()=>Math.min(cycle==='small'?.5:1,methodCap??1);
 function values(){return{entry:number($('#goldSizingEntry')),stop:number($('#goldSizingStop')),riskPercent:number($('#goldSizingPercent')),accountId:$('#goldSizingAccount').value}}
 function calculate(notify=false){
  const account=getAccount(),input=values(),result=simpleSizing({equity:account?.equity??null},{...input,direction:card.direction,multiplier:spec?.pointValue??null,tickSize:spec?.tickSize??null});
  const over=input.riskPercent>cap();$('#goldSizingPercent').max=cap();$('#goldSizingEquity').value=fmt(account?.equity);
  $('#goldSizingBudget').value=fmt(result.frozenBudget);$('#goldSizingDistance').value=fmt(result.stopDistance,6);$('#goldSizingPerLot').value=fmt(result.riskPerLot);
  $('#goldSizingLots').value=over?'待核验':fmt(result.lots,0);
  const missing=over?[`当前主周期风险比例上限为 ${cap()}%`]:result.missing;
  $('#goldSizingFeedback').textContent=missing.length?missing.join('；'):result.lots===0?'当前亏损额度不足一手':`${fmt(result.frozenBudget)} ÷ ${fmt(result.riskPerLot)}，向下取整 ${fmt(result.lots,0)} 手；价差止损约 ${fmt(result.plannedLoss)} 元。`;
  $('#goldSizingFeedback').className=missing.length||result.lots===0?'hint warning':'hint';
  if(manual&&!suppress&&card.id)manualDrafts.set(card.id,{...input,mainCycle:cycle});if(notify&&!suppress)onChange?.({...input,result:over?{...result,lots:null}:result});return result;
 }
 async function refreshAccounts(){const request=++revision;try{const next=await api('/api/workbench/accounts');if(!node.isConnected||request!==revision)return;available=next.filter(a=>a.status==='active');const selected=$('#goldSizingAccount').value;$('#goldSizingAccount').innerHTML=available.map(a=>`<option value="${esc(a.id)}" ${a.id===selected?'selected':''}>${esc(a.alias)}</option>`).join('');calculate(true)}catch(e){if(node.isConnected)$('#goldSizingFeedback').textContent='账户余额未更新：'+e.message}}
 function setPrices(next,{isManual=false,notify=true}={}){suppress=true;for(const [key,id]of [['entry','goldSizingEntry'],['stop','goldSizingStop'],['riskPercent','goldSizingPercent']])if(next[key]!==undefined)$('#'+id).value=next[key]??'';if(next.accountId&&available.some(a=>a.id===next.accountId))$('#goldSizingAccount').value=next.accountId;if(next.mainCycle)cycle=next.mainCycle;suppress=false;if(isManual)manual=true;return calculate(notify)}
 function suggest(d){if(!d)return;source=d;methodCap=d.maxRiskPercent??null;const extra=d.method==='intraday'?{mainCycle:'small',riskPercent:Math.min(values().riskPercent??.5,.5)}:{};if(d.method==='intraday')setPrices(extra,{notify:false});$('#goldSizingSuggestion').textContent=`系统参考：入场 ${fmt(d.entry,6)} · 结构止损 ${fmt(d.stop,6)}。${d.method==='intraday'?'独立分时上限0.5%，入场价仍须本人填写。':'最终以你的手动输入为准。'}`;$('#goldSizingSuggestionButton').disabled=false;if(!manual)setPrices({entry:d.entry,stop:d.stop,...extra},{notify:true})}
 $('#goldSizingSuggestionButton').onclick=()=>{manual=false;if(source)setPrices({entry:source.entry,stop:source.stop},{notify:true})};
 for(const id of ['goldSizingEntry','goldSizingStop','goldSizingPercent'])$('#'+id).oninput=()=>{manual=true;calculate(true)};
 $('#goldSizingForm').onsubmit=e=>{e.preventDefault();calculate(true)};$('#goldSizingAccount').oninput=()=>calculate(true);
 $('#goldSizingAccount').onchange=()=>{calculate(true);void refreshAccounts()};$('#goldSizingRefresh').onclick=()=>void refreshAccounts();
 void refreshAccounts();void api('/api/workbench/contract-spec?symbol='+encodeURIComponent(card.symbol)).then(value=>{if(!node.isConnected)return;spec=value;$('#goldSizingEntry').step=spec.tickSize;$('#goldSizingStop').step=spec.tickSize;$('#goldSizingSpec').textContent=`${spec.name||card.name}：每点每手 ${fmt(spec.pointValue)} 元；最小变动 ${fmt(spec.tickSize,6)} 点，每跳 ${fmt(spec.tickValue)} 元／手。`;calculate(true)}).catch(e=>{if(node.isConnected){$('#goldSizingSpec').textContent='合约参数未取得：'+e.message;calculate()}});
 calculate();return{values,calculate,setPrices,suggest,previewFor(input){const account=available.find(a=>a.id===input.accountId);return simpleSizing({equity:account?.equity??null},{...input,direction:card.direction,multiplier:spec?.pointValue??null,tickSize:spec?.tickSize??null})},setCycle(value){cycle=value;calculate(true)}};
}
